```python
import unittest

def divide(a, b):
    return a / b

class TestDivision(unittest.TestCase):

    def test_divide_positive_numbers(self):
        """Проверяет корректность деления двух положительных чисел."""
        self.assertEqual(divide(10, 2), 5)

    def test_divide_zero_and_positive_number(self):
        """Проверяет корректность деления положительного числа на ноль."""
        with self.assertRaises(ZeroDivisionError):
            divide(10, 0)

    def test_divide_negative_numbers(self):
        """Проверяет корректность деления двух отрицательных чисел."""
        self.assertEqual(divide(-10, -2), 5)

    def test_divide_zero_and_negative_number(self):
        """Проверяет корректность деления отрицательного числа на ноль."""
        with self.assertRaises(ZeroDivisionError):
            divide(-10, 0)

    def test_divide_mixed_signs(self):
        """Проверяет корректность деления чисел с разными знаками."""
        self.assertEqual(divide(10, -2), -5)

if __name__ == '__main__':
    unittest.main()
```

