```python
def normalize_name(name):
    return name.strip().title()

import unittest

class TestNameNormalization(unittest.TestCase):

    def test_strip_and_title(self):
        """
        Проверяет, что функция корректно удаляет начальные и конечные пробелы и приводит строку к заглавному регистру.
        """
        self.assertEqual(normalize_name("  john  "), "John")

    def test_empty_string(self):
        """
        Проверяет, что функция корректно обрабатывает пустую строку.
        """
        self.assertEqual(normalize_name(""), "")

    def test_single_character(self):
        """
        Проверяет, что функция корректно обрабатывает строку из одного символа.
        """
        self.assertEqual(normalize_name("a"), "A")

if __name__ == '__main__':
    unittest.main()
```

