```python
import unittest

def merge_dicts(a, b):
    result = a.copy()
    result.update(b)
    return result

class TestMergeDicts(unittest.TestCase):

    # Позитивные тесты
    def test_merge_dicts_with_non_empty_dicts(self):
        """
        Тест для слияния двух непустых словарей.
        """
        a = {'a': 1, 'b': 2}
        b = {'b': 3, 'c': 4}
        expected = {'a': 1, 'b': 3, 'c': 4}
        self.assertEqual(merge_dicts(a, b), expected)

    def test_merge_dicts_with_identical_keys(self):
        """
        Тест для слияния двух словарей с одинаковыми ключами.
        """
        a = {'x': 10, 'y': 20}
        b = {'x': 30, 'z': 40}
        expected = {'x': 30, 'y': 20, 'z': 40}
        self.assertEqual(merge_dicts(a, b), expected)

    # Негативные тесты
    def test_merge_dicts_with_non_dict_argument(self):
        """
        Тест для проверки, что функция вызывает ошибку при передаче не словаря.
        """
        a = {'a': 1, 'b': 2}
        with self.assertRaises(TypeError):
            merge_dicts(a, 'not_a_dict')

    def test_merge_dicts_with_none_argument(self):
        """
        Тест для проверки, что функция вызывает ошибку при передаче None.
        """
        a = {'a': 1, 'b': 2}
        with self.assertRaises(TypeError):
            merge_dicts(a, None)

    # Граничные случаи
    def test_merge_dicts_with_empty_dict(self):
        """
        Тест для слияния словаря с пустым словарём.
        """
        a = {'a': 1, 'b': 2}
        b = {}
        expected = {'a': 1, 'b': 2}
        self.assertEqual(merge_dicts(a, b), expected)

    def test_merge_dicts_with_one_empty_dict(self):
        """
        Тест для слияния пустого словаря с непустым.
        """
        a = {}
        b = {'a': 1, 'b': 2}
        expected = {'a': 1, 'b': 2}
        self.assertEqual(merge_dicts(a, b), expected)

if __name__ == '__main__':
    unittest.main()
```

