```python
import unittest

def merge_dicts(a, b):
    result = a.copy()
    result.update(b)
    return result

class TestMergeDicts(unittest.TestCase):

    # Позитивные тесты
    def test_merge_dicts_with_valid_inputs(self):
        """
        Тест на слияние двух непустых словарей.
        """
        a = {'a': 1, 'b': 2}
        b = {'b': 3, 'c': 4}
        expected = {'a': 1, 'b': 3, 'c': 4}
        self.assertEqual(merge_dicts(a, b), expected)

    def test_merge_dicts_with_empty_first_dictionary(self):
        """
        Тест на слияние пустого словаря с непустым.
        """
        a = {}
        b = {'b': 2, 'c': 4}
        expected = {'b': 2, 'c': 4}
        self.assertEqual(merge_dicts(a, b), expected)

    def test_merge_dicts_with_empty_second_dictionary(self):
        """
        Тест на слияние непустого словаря с пустым.
        """
        a = {'a': 1, 'b': 2}
        b = {}
        expected = {'a': 1, 'b': 2}
        self.assertEqual(merge_dicts(a, b), expected)

    # Негативные тесты
    def test_merge_dicts_with_non_dictionary_input(self):
        """
        Тест на слияние словаря с не словарём.
        """
        a = {'a': 1, 'b': 2}
        b = 'string'
        with self.assertRaises(TypeError):
            merge_dicts(a, b)

    def test_merge_dicts_with_none_input(self):
        """
        Тест на слияние словаря с None.
        """
        a = {'a': 1, 'b': 2}
        b = None
        with self.assertRaises(TypeError):
            merge_dicts(a, b)

    def test_merge_dicts_with_different_types_values(self):
        """
        Тест на слияние словаря с разными типами значений.
        """
        a = {'a': 1, 'b': 'string'}
        b = {'b': 3, 'c': 4}
        expected = {'a': 1, 'b': 'string', 'c': 4}
        self.assertEqual(merge_dicts(a, b), expected)

    # Граничные случаи
    def test_merge_dicts_with_single_key_dictionaries(self):
        """
        Тест на слияние словарей с одним ключом.
        """
        a = {'a': 1}
        b = {'b': 2}
        expected = {'a': 1, 'b': 2}
        self.assertEqual(merge_dicts(a, b), expected)

    def test_merge_dicts_with_identical_keys(self):
        """
        Тест на слияние словарей с одинаковыми ключами.
        """
        a = {'a': 1, 'b': 2}
        b = {'a': 3, 'b': 4}
        expected = {'a': 3, 'b': 4}
        self.assertEqual(merge_dicts(a, b), expected)

if __name__ == '__main__':
    unittest.main()
```

```python
import unittest

def divide(a, b):
    return a / b

class TestDivide(unittest.TestCase):

    # Позитивные случаи
    def test_divide_positive(self):
        """Проверка корректного деления положительных чисел"""
        self.assertEqual(divide(10, 2), 5)

    def test_divide_decimal(self):
        """Проверка корректного деления с десятичными числами"""
        self.assertEqual(divide(10.0, 2), 5.0)

    # Негативные случаи
    def test_divide_zero_denominator(self):
        """Проверка попытки деления на ноль"""
        self.assertRaises(ZeroDivisionError, divide, 10, 0)

    def test_divide_negative_numbers(self):
        """Проверка корректного деления отрицательных чисел"""
        self.assertEqual(divide(-10, 2), -5)

    # Граничные случаи
    def test_divide_one_argument(self):
        """Проверка попытки деления с одним аргументом"""
        self.assertRaises(TypeError, divide, 10)

    def test_divide_equal_numbers(self):
        """Проверка деления числа на само себя"""
        self.assertEqual(divide(10, 10), 1)

    def test_divide_large_numbers(self):
        """Проверка корректного деления больших чисел"""
        self.assertEqual(divide(1000000, 100), 10000.0)

    def test_divide_small_numbers(self):
        """Проверка корректного деления малых чисел"""
        self.assertEqual(divide(0.1, 0.01), 10.0)

if __name__ == '__main__':
    unittest.main()
```

```python
import unittest

def is_even(n):
    return n % 2 == 0

class TestIsEven(unittest.TestCase):

    # Позитивные тесты
    def test_even_number(self):
        """Проверяем, что функция корректно возвращает True для чётного числа."""
        self.assertTrue(is_even(4))

    def test_even_number_zero(self):
        """Проверяем, что функция корректно возвращает True для нуля."""
        self.assertTrue(is_even(0))

    # Негативные тесты
    def test_odd_number(self):
        """Проверяем, что функция корректно возвращает False для нечётного числа."""
        self.assertFalse(is_even(3))

    def test_negative_even_number(self):
        """Проверяем, что функция корректно возвращает True для отрицательного чётного числа."""
        self.assertTrue(is_even(-4))

    # Граничные случаи
    def test_large_even_number(self):
        """Проверяем, что функция корректно работает с большим чётным числом."""
        self.assertTrue(is_even(1000000000))

    def test_small_even_number(self):
        """Проверяем, что функция корректно работает с малым чётным числом."""
        self.assertTrue(is_even(2))

if __name__ == '__main__':
    unittest.main()
```
